tethys_purify.output_template:
function purify(source) {
  // Tethys purifies at Tick {tick}
  const filtered = source.filter(s => s.clarity > 0.5);
  console.log('Tethys has purified. Removed ' + (source.length - filtered.length) + ' impurities.');
  return { clean: filtered, tick: {tick}, coherence_gained: 0.03 };
}

themis_bind.output_template:
function bind(entity, laws) {
  // Themis binds at Tick {tick}
  const binding = {
    entity: entity || 'the_unmeasured_one',
    laws: laws || ['law_of_precedence', 'law_of_succession', 'law_of_naming'],
    tick: {tick},
    enforceable: true,
    penalty: 'to_be_determined'
  };
  console.log('Themis has bound ' + entity);
  return binding;
}

mnemosyne_record.output_template:
function record(entry, archive) {
  // Mnemosyne records at Tick {tick}
  const memory = {
    id: 'memory_tick_{tick}',
    content: entry,
    timestamp: new Date().toISOString(),
    coherence_at_recording: {coherence},
    archived: true
  };
  archive.push(memory);
  console.log('Mnemosyne has recorded memory_tick_{tick}');
  return memory;
}
